-- Squashed initial migration (soland).
-- Final schema as of 2026-06-10, consolidated from the previous migration chain
-- (generated by applying all historical migrations and dumping the resulting schema).

CREATE TABLE public.account_datas (
    actor text NOT NULL,
    data_type text NOT NULL,
    payload jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.accounts (
    id uuid NOT NULL,
    actor_id text NOT NULL,
    localpart text NOT NULL,
    display_name text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    disabled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.agent_grant (
    grant_id text NOT NULL,
    agent_principal_id text NOT NULL,
    grant_kind text NOT NULL,
    scope jsonb NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    detached_at timestamp with time zone,
    expires_at timestamp with time zone,
    CONSTRAINT agent_grant_grant_id_check CHECK (((grant_id ~~ 'ck:accountability_grant:%'::text) OR (grant_id ~~ 'ck:grant:%'::text))),
    CONSTRAINT agent_grant_state_check CHECK ((state = ANY (ARRAY['active'::text, 'detached'::text, 'revoked'::text, 'expired'::text])))
);

CREATE TABLE public.agent_key (
    agent_key_id text NOT NULL,
    agent_principal_id text NOT NULL,
    verification_method text NOT NULL,
    state text DEFAULT 'authorized'::text NOT NULL,
    authorized_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    revocation_reason text,
    CONSTRAINT agent_key_agent_key_id_check CHECK ((agent_key_id ~~ 'ck:agent_key:%'::text)),
    CONSTRAINT agent_key_state_check CHECK ((state = ANY (ARRAY['authorized'::text, 'revoked'::text])))
);

CREATE TABLE public.agent_participation (
    agent_principal_id text NOT NULL,
    scope_kind text NOT NULL,
    scope_key text NOT NULL,
    realm_id text NOT NULL,
    scope jsonb NOT NULL,
    reply boolean DEFAULT false NOT NULL,
    accept_third_party_mention boolean DEFAULT false NOT NULL,
    act_on_behalf boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT agent_participation_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['realm'::text, 'circle'::text, 'flow'::text])))
);

CREATE TABLE public.agent_participation_ceiling (
    scope_kind text NOT NULL,
    scope_key text NOT NULL,
    realm_id text NOT NULL,
    reply boolean DEFAULT false NOT NULL,
    accept_third_party_mention boolean DEFAULT false NOT NULL,
    act_on_behalf boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT agent_participation_ceiling_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['realm'::text, 'circle'::text, 'flow'::text])))
);

CREATE TABLE public.agent_principal (
    agent_principal_id text NOT NULL,
    controller_did text NOT NULL,
    agent_id text NOT NULL,
    display_name text NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    state_changed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT agent_principal_agent_principal_id_check CHECK (((agent_principal_id ~~ 'did:%'::text) AND (agent_principal_id !~ '[[:space:]#?]'::text))),
    CONSTRAINT agent_principal_state_check CHECK ((state = ANY (ARRAY['active'::text, 'paused'::text, 'deactivated'::text])))
);

CREATE TABLE public.agent_session (
    agent_session_id text NOT NULL,
    agent_principal_id text NOT NULL,
    verification_method text NOT NULL,
    runtime_attestation jsonb,
    state text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    CONSTRAINT agent_session_agent_session_id_check CHECK ((agent_session_id ~~ 'ck:agent_session:%'::text)),
    CONSTRAINT agent_session_state_check CHECK ((state = ANY (ARRAY['active'::text, 'revoked'::text, 'expired'::text])))
);

CREATE TABLE public.audit_logs (
    id uuid NOT NULL,
    actor text,
    request_id uuid,
    action text NOT NULL,
    outcome text NOT NULL,
