CREATE SEQUENCE public.projection_events_ordinal_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.projection_events_ordinal_seq OWNED BY public.projection_events.ordinal;

